joinIdempotent : Idempotent _∨_
1 clause(s), 4 step(s), lemmas: (none)

clause joinIdempotent x
  goal: _∨_ IdempotentOn x
  1. x ∨ x ≈ (x + x) + (x * x)
       by {!!}
  2. (x + x) + (x * x) ≈ (x + x) + x
       by {!!}
  3. (x + x) + x ≈ x + x
       by {!!}
  4. x + x ≈ x
       by {!!}

