distribRight3 : (u v w z : Carrier) → (u + v + w) * z ≈ u * z + v * z + w * z
1 clause(s), 3 step(s), lemmas: (none)

clause distribRight3 u v w z
  goal: (u + v + w) * z ≈ u * z + v * z + w * z
  1. ((u + v) + w) * z ≈ (u + v) * z + w * z
       by {!!}
  2. (u + v) * z + w * z ≈ (u * z + v * z) + w * z
       by {!!}
  3. (u * z + v * z) + w * z ≈ u * z + v * z + w * z
       by {!!}
